// Turns per-item exports from Zotero into one deterministic .bib file. Determinism matters:
// the same library state must always produce byte-identical output so we never push noise.

import type { ItemInfo } from "./zotero/client.ts";

export const BIB_HEADER = [
  "% This file is generated by zotero-sharelatex-sync from Zotero.",
  "% Do not edit it here: manual changes are overwritten on the next sync.",
].join("\n");

const SKIPPED_TYPES = new Set(["note", "attachment", "annotation"]);
const ENTRY_HEAD = /^(\s*@[A-Za-z]+\s*[{(]\s*)([^,\s]+)/;

export interface BibResult {
  content: string;
  entryCount: number;
  /** Items whose citation key collided with an older item and got a suffix. */
  renamed: { itemKey: string; from: string; to: string }[];
  /** Items that produced no usable entry. */
  skipped: { itemKey: string; reason: string }[];
}

export function citationKey(entry: string): string | undefined {
  return ENTRY_HEAD.exec(entry)?.[2];
}

function compareItems(a: ItemInfo, b: ItemInfo): number {
  if (a.dateAdded !== b.dateAdded) return a.dateAdded < b.dateAdded ? -1 : 1;
  return a.key < b.key ? -1 : a.key > b.key ? 1 : 0;
}

export function buildBibliography(items: ItemInfo[]): BibResult {
  const unique = new Map<string, ItemInfo>();
  for (const item of items) unique.set(item.key, item);

  const skipped: BibResult["skipped"] = [];
  const keyed: { item: ItemInfo; citeKey: string; entry: string }[] = [];
  for (const item of [...unique.values()].sort(compareItems)) {
    if (item.deleted || SKIPPED_TYPES.has(item.itemType)) continue;
    const entry = item.entry.trim();
    const citeKey = citationKey(entry);
    if (!citeKey) {
      skipped.push({ itemKey: item.key, reason: entry ? "unparseable entry" : "empty export" });
      continue;
    }
    keyed.push({ item, citeKey, entry });
  }

  // Oldest item keeps its key; later items with the same key get -2, -3, ... (case-insensitive,
  // because biber treats keys case-insensitively).
  const taken = new Set<string>();
  const renamed: BibResult["renamed"] = [];
  const entries: { citeKey: string; itemKey: string; entry: string }[] = [];
  for (const { item, citeKey, entry } of keyed) {
    let finalKey = citeKey;
    for (let n = 2; taken.has(finalKey.toLowerCase()); n++) finalKey = `${citeKey}-${n}`;
    taken.add(finalKey.toLowerCase());
    if (finalKey !== citeKey) renamed.push({ itemKey: item.key, from: citeKey, to: finalKey });
    entries.push({
      citeKey: finalKey,
      itemKey: item.key,
      entry: finalKey === citeKey ? entry : entry.replace(ENTRY_HEAD, `$1${finalKey}`),
    });
  }

  entries.sort((a, b) => {
    const ka = a.citeKey.toLowerCase();
    const kb = b.citeKey.toLowerCase();
    if (ka !== kb) return ka < kb ? -1 : 1;
    return a.itemKey < b.itemKey ? -1 : 1;
  });

  const body = entries.map((e) => e.entry).join("\n\n");
  return {
    content: `${BIB_HEADER}\n${body ? `\n${body}\n` : ""}`,
    entryCount: entries.length,
    renamed,
    skipped,
  };
}
